<script lang="ts">
  import { untrack } from 'svelte'; import { slugify } from '#lib/slug.ts'; import type { Product, ProductInput } from '@orbita/contracts'; import { graphql, request } from '#lib/api.ts'; import { CREATE, UPDATE } from '#lib/queries.ts';
  let { product = null, categories, units, writesEnabled = false }: { product?: Product | null; categories: {id:string;value:string}[]; units:{value:string}[]; writesEnabled?:boolean } = $props();
  let value = $state(untrack(() => product?.value || '')); let slug = $state(untrack(() => product?.slug || '')); let categoryId = $state(untrack(() => product?.categoryId || ''));
  let price = $state(untrack(() => product?.price?.value || '')); let unit = $state(untrack(() => product?.unit?.value || 'шт')); let active = $state(untrack(() => product?.is_active ?? true));
  let uploadedUrl = $state('');
  let imageHash = $state(untrack(() => product?.image?.hash || '')); let imageAlt = $state(untrack(() => product?.image?.alt || ''));
  let texts = $state(untrack(() => (product?.text || []).map(t => ({ id: t.id, slug: t.slug || '', value: t.value }))));
  let properties = $state(untrack(() => (product?.property || []).map(t => ({ id: t.id, slug: t.slug || '', value: t.value }))));
  let ready = $state(false); $effect(() => { ready = true; });
  let pending = $state(false); let uploading = $state(false); let message = $state(''); let fileInput: HTMLInputElement;
  async function upload() {
    const file = fileInput?.files?.[0]; if (!file) return; uploading = true; message = '';
    try { const body = new FormData(); body.set('image', file); const data = await request<{hash:string;url:string}>('/api/media', { method:'POST', body }); imageHash = data.hash; uploadedUrl = data.url; if (!imageAlt) imageAlt = value; }
    catch (e) { message = (e as Error).message; } finally { uploading = false; }
  }
  async function save(event: SubmitEvent) {
    event.preventDefault(); if (!writesEnabled) return; pending = true; message = '';
    try { const input: ProductInput = { value: value.trim(), slug: slug.trim() || slugify(value), categoryId, price: price.replace(',', '.'), unit, is_active:active, ...(!product || imageHash !== (product.image?.hash || '') ? {imageHash: imageHash || null} : {}), ...(!product || imageAlt !== (product.image?.alt || '') ? {imageAlt: imageAlt || null} : {}), texts: texts.map(({id,slug,value}) => ({ ...(id ? {id}:{}), slug:slug||null, value })), properties: properties.map(({id,slug,value}) => ({ ...(id ? {id}:{}), slug:slug||null, value })) };
      const data = await graphql<{createProduct?:Product;updateProduct?:Product}>(product ? UPDATE : CREATE, { ...(product ? {id:product.id} : {}), input });
      const result = data.updateProduct || data.createProduct; if (!result) throw new Error('Сервер не подтвердил сохранение'); window.location.assign(`/admin/products/${result.id}?saved=1`);
    } catch (e) { message = (e as Error).message; } finally { pending = false; }
  }
</script>
<form class="mt-6 space-y-6" onsubmit={save}>
  {#if !writesEnabled}<p class="notice">Изменения каталога временно недоступны. Просмотр карточек продолжает работать.</p>{/if}
  {#if message}<p class="notice notice-error" role="alert">{message}</p>{/if}
  <fieldset disabled={pending || !writesEnabled || !ready} class="grid gap-6 lg:grid-cols-[minmax(0,2fr)_minmax(0,1fr)]">
    <div class="space-y-6">
      <section class="card space-y-5"><h2 class="text-xl font-bold">Карточка товара</h2><div><label class="label" for="name">Название</label><input class="field" id="name" required maxlength="255" bind:value={value}/></div><div><label class="label" for="slug">Адрес страницы</label><input class="field" id="slug" maxlength="255" pattern="[a-z0-9]+(?:-[a-z0-9]+)*" bind:value={slug}/><p class="mt-2 text-sm text-muted">Оставьте пустым, чтобы сформировать адрес из названия. Изменение адреса может повлиять на существующие ссылки.</p></div><div><label class="label" for="category">Категория</label><select class="field" id="category" required bind:value={categoryId}><option value="">Выберите категорию</option>{#each categories as category}<option value={category.id}>{category.value}</option>{/each}</select></div><div class="grid gap-4 sm:grid-cols-2"><div><label class="label" for="price">Цена, ₽</label><input class="field" id="price" inputmode="decimal" pattern={'[0-9]+([.,][0-9]{1,2})?'} required bind:value={price}/></div><div><label class="label" for="unit">Единица измерения</label><input class="field" id="unit" required list="units" bind:value={unit}/><datalist id="units">{#each units as item}<option value={item.value}></option>{/each}</datalist></div></div><label class="flex min-h-11 items-center gap-3"><input type="checkbox" class="size-5 accent-brand" bind:checked={active}/>Показывать в витрине</label></section>
      <section class="card space-y-4"><div class="flex flex-wrap items-center justify-between gap-3"><h2 class="text-xl font-bold">Описание</h2><button class="button button-secondary" type="button" onclick={() => texts.push({id:undefined,slug:'description',value:''})}>Добавить текст</button></div>{#each texts as text, index}<div class="grid gap-3 border-t border-slate-200 pt-4"><label class="label" for={`text-key-${index}`}>Обозначение текста</label><input class="field" id={`text-key-${index}`} bind:value={text.slug}/><label class="label" for={`text-value-${index}`}>Содержание</label><textarea class="field min-h-32" id={`text-value-${index}`} bind:value={text.value}></textarea><button class="button button-secondary justify-self-start" type="button" onclick={() => texts.splice(index,1)}>Убрать текст</button></div>{:else}<p class="text-sm text-muted">У товара пока нет описания.</p>{/each}</section>
      <section class="card space-y-4"><div class="flex flex-wrap items-center justify-between gap-3"><h2 class="text-xl font-bold">Характеристики</h2><button class="button button-secondary" type="button" onclick={() => properties.push({id:'',slug:'',value:''})}>Добавить характеристику</button></div>{#each properties as item,index}<div class="grid gap-3 border-t border-slate-200 pt-4 sm:grid-cols-[1fr_1fr_auto]"><div><label class="label" for={`property-key-${index}`}>Обозначение</label><input class="field" id={`property-key-${index}`} bind:value={item.slug}/></div><div><label class="label" for={`property-value-${index}`}>Значение</label><input class="field" id={`property-value-${index}`} required bind:value={item.value}/></div><button class="button button-secondary mt-auto" type="button" aria-label={`Убрать характеристику ${item.slug || index+1}`} onclick={() => properties.splice(index,1)}>Убрать</button></div>{:else}<p class="text-sm text-muted">Характеристики не добавлены.</p>{/each}</section>
    </div>
    <section class="card self-start space-y-4"><h2 class="text-xl font-bold">Изображение</h2>{#if imageHash}<img class="aspect-square w-full rounded object-contain" src={uploadedUrl || product?.image?.url || `https://lumen-image-bucket.s3.eu-central-1.amazonaws.com/images/${encodeURIComponent(imageHash)}`} alt={imageAlt || value}/>{:else}<div class="flex aspect-square items-center justify-center rounded bg-slate-100 text-muted">Нет изображения</div>{/if}<div><label class="label" for="image">JPEG, PNG или WebP, до 10 МБ</label><input class="field" id="image" type="file" accept="image/jpeg,image/png,image/webp" bind:this={fileInput}/></div><button type="button" class="button button-secondary" onclick={upload} disabled={uploading}>{uploading ? 'Загружаем…' : 'Загрузить изображение'}</button><div><label class="label" for="alt">Описание изображения</label><input class="field" id="alt" maxlength="255" bind:value={imageAlt}/></div>{#if imageHash}<button type="button" class="button button-secondary" onclick={() => { imageHash=''; imageAlt=''; uploadedUrl=''; }}>Убрать из карточки</button>{/if}</section>
  </fieldset>
  <div class="flex flex-wrap gap-3"><button class="button" disabled={pending || uploading || !writesEnabled || !ready}>{pending ? 'Сохраняем…' : 'Сохранить товар'}</button><a class="button button-secondary" href="/admin/products">К списку товаров</a></div>
</form>
